import { initIPAIndexPage } from '../js/page/ipa-index-page.js';
import { processTextCharBased } from '../js/ipa.js';
import {
  formatIPA_org,
  formatIPA_num,
  formatYueJyutping,
  formatYueGuangzhou,
  formatYueAcademy,
  formatYueYale,
  formatYueLiu
